'use strict';
const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)],esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let contentMeta={},updateStatus=null,refreshing=false,lastContentCheck=0;
let data=[],filter='すべて',duration='all',activeArticle=null,raf=0,expType='pendulum';
let state={saved:[],visits:{},reencounters:{},channelSaves:[]};
try{const s=JSON.parse(localStorage.getItem('curiosity-lab-v1'));if(s&&Array.isArray(s.saved)&&s.visits&&s.reencounters)state={...s,channelSaves:Array.isArray(s.channelSaves)?s.channelSaves.filter(id=>typeof id==='string'):[]}}catch{}
function persist(){try{localStorage.setItem('curiosity-lab-v1',JSON.stringify(state));return true}catch{toast('保存容量が不足しています。データを書き出してください。');return false}}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3000)}
function save(id){const prev=[...state.saved];state.saved=state.saved.includes(id)?state.saved.filter(x=>x!==id):[...state.saved,id];if(!persist()){state.saved=prev;return}updateCount();$$(`[data-save="${id}"]`).forEach(b=>{b.classList.toggle('saved',state.saved.includes(id));b.textContent=state.saved.includes(id)?'✓':'+';b.setAttribute('aria-label',state.saved.includes(id)?'保存を解除':'発見を保存')});toast(state.saved.includes(id)?'コレクションに保存しました':'保存を解除しました');if(location.hash==='#collection')render()}
function updateCount(){$('#save-count').textContent=state.saved.length}
const cats=['すべて','宇宙','自然','科学','歴史','文化','心理','技術','日常'];
function chips(){return `<div class="explore-bar">${cats.map(c=>`<button class="chip ${filter===c?'active':''}" data-filter="${c}" aria-pressed="${filter===c}">${c}</button>`).join('')}<button class="random" data-random><span>⤨</span>偶然にまかせる</button></div>`}
function card(a){return `<article class="exhibit" tabindex="0" role="button" data-article="${a.id}" aria-label="${esc(a.title)}"><div class="exhibit-media"><img src="./assets/${a.image}.jpg" alt="${esc(a.subtitle)}のイメージ写真" loading="lazy"><span class="image-number">FIELD NOTE / ${String(a.number).padStart(2,'0')}</span><button class="bookmark ${state.saved.includes(a.id)?'saved':''}" data-save="${a.id}" aria-label="${state.saved.includes(a.id)?'保存を解除':'発見を保存'}">${state.saved.includes(a.id)?'✓':'+'}</button></div><div class="meta"><span class="category">${a.category} / ${({宇宙:'COSMOS',自然:'NATURE',科学:'SCIENCE',歴史:'HISTORY',文化:'CULTURE',心理:'MIND',技術:'TECHNOLOGY',日常:'EVERYDAY'})[a.category]}</span><span>本文 約${readingMinutes(a)}分</span></div><h3>${esc(a.title)}</h3><p>${esc(a.subtitle)}</p><div class="bottom"><span>${state.visits[a.id]?'出会った知識':'まだ知らない世界へ'}</span><span>↗</span></div></article>`}
function filtered(items){return items.filter(a=>(filter==='すべて'||a.category===filter)&&(duration==='all'||(duration==='10'?readingMinutes(a)<=10:readingMinutes(a)<=Number(duration))))}
function dueArticle(){return data.filter(a=>{let v=state.visits[a.id];return v&&Date.now()-v.first>=3*86400000&&Date.now()-(state.reencounters[a.id]||0)>=7*86400000}).sort((a,b)=>(state.reencounters[a.id]||0)-(state.reencounters[b.id]||0))[0]}
function heading(en,title,desc,controls=''){return `<div class="section-heading"><div><div class="eyebrow">${en}</div><h2>${title}</h2>${desc?`<p>${desc}</p>`:''}</div>${controls}</div>`}
function discover(){const due=dueArticle();return `<div class="page"><div class="intro"><div><div class="eyebrow">FOLLOW YOUR CURIOSITY</div><h1>世界は、まだ面白い。</h1><p>知るたびに、いつもの景色が少し変わる。</p></div><div class="date-mark">YOUR POCKET MUSEUM<br>Vol. 001 / OPEN 24 HOURS</div></div>${updatePanel()}<section class="hero" role="button" tabindex="0" data-article="stardust" aria-label="私たちは星のかけらでできているを読む"><img src="./assets/space.jpg" alt="無数の星がきらめく星雲"><div class="hero-index">01 <span>/ THE UNIVERSE & US</span></div><div class="hero-copy"><div class="exhibit-label">今夜、ひとつの不思議を。</div><h2>私たちは、星のかけらで<br>できている。</h2><p>あなたの体にある炭素も、呼吸する酸素も。<br>はるか昔、星の中で生まれたものかもしれない。</p><span class="pill">この世界をのぞく <span>↗</span></span></div><div class="hero-foot">COSMOS　·　FOLLOW YOUR CURIOSITY</div></section>${roomIndex()}${channelTeaser()}${chips()}${due?`<section class="resurface" data-revisit="${due.id}" tabindex="0" role="button"><div class="eyebrow">HELLO, AGAIN</div><h3>もう一度、違う角度から。</h3><p>${esc(due.revisit)}</p><span class="text-link">${esc(due.title)} ↗</span></section>`:''}${heading('CABINET OF WONDERS','今日は、どこへ寄り道する？','小さな発見から、思いがけない世界へ。',`<select id="duration" aria-label="読む時間"><option value="all">時間を気にせず</option value="3">本文 約3分以内</option value="5">本文 約5分以内</option value="10">本文 約10分以内</option></select>`)}<div class="exhibits" id="exhibits">${filtered(data.filter(x=>filter!=='すべて'||x.id!=='stardust')).map(card).join('')||'<p class="empty">この条件の展示は準備中です。別の分野も巡ってみませんか。</p>'}</div><section class="lab-teaser"><div class="copy"><div class="eyebrow">THE INTERACTIVE LAB</div><h2>読むだけじゃ、<br>わからないこともある。</h2><p>動かして、比べて、「なるほど」に出会う。</p><a class="text-link" href="#lab">実験室の扉を開く　↗</a></div><div class="wave-art"><div class="orb"></div></div></section>${heading('WATCH & WONDER','映像で、腑に落ちる。','図解とアニメーションで、知識の入口へ。',`<a href="#videos" class="text-link">動画の展示室 ↗</a>`)}<div class="video-grid">${videoList().slice(0,2).map(videoCard).join('')}</div></div>`}
function readingMinutes(a){return Math.max(1,Math.ceil((a.summary.length+a.sections.reduce((n,s)=>n+s.text.length,0))/350))}
function videoList(){const seen=new Set();return data.flatMap(a=>(a.videos||[]).map(v=>({...v,articleId:a.id,image:a.image}))).filter(v=>{if(seen.has(v.url))return false;seen.add(v.url);return true})}
function videoCard(v){const language={ja:'日本語音声','ja-subtitles':'日本語字幕','ja-text':'日本語解説付き観察映像'}[v.language];return `<article class="video"><div class="video-preview">${v.id?`<img loading="lazy" src="https://i.ytimg.com/vi/${esc(v.id)}/hqdefault.jpg" alt="${esc(v.title)}の動画サムネイル"><button class="play" data-video="${esc(v.id)}" aria-label="${esc(v.title)}を再生">▶</button>`:`<img loading="lazy" src="./assets/${esc(v.image||data.find(a=>a.id===v.key)?.image)}.jpg" alt="テーマのイメージ"><a class="play" href="${esc(v.url)}" target="_blank" rel="noopener" aria-label="${esc(v.title)}の視聴ページを開く">↗</a>`}</div><div class="meta"><span>${esc(language)}</span><span>${v.level?esc(v.level)+' · ':''}${v.relation==='related'?'関連テーマの補足':'テーマの参考動画'}</span></div><h3>${esc(v.title)}</h3><p class="video-provider">${esc(v.provider)}</p><p>${esc(v.note)}</p><a class="text-link" href="${esc(v.url)}" target="_blank" rel="noopener">${v.id?'YouTube':'日本語の視聴ページ'}で見る ↗</a><details class="evaluation"><summary>選定根拠・評価について</summary><p>公開元の案内で内容と日本語での確認方法を確認（${esc(v.checked)}）。全編の実視聴評価は未完了のため、点数・順位は付けていません。外部サイト側の公開状態や字幕は変更される場合があります。</p><dl><dt>図・実験・実物</dt><dd>未採点 / 30</dd><dt>初心者向けの構成</dt><dd>未採点 / 25</dd><dt>説明と映像の一致</dt><dd>未採点 / 20</dd><dt>正確性・出典</dt><dd>未採点 / 15</dd><dt>テンポ・見やすさ</dt><dd>未採点 / 10</dd></dl></details>${v.articleId?`<button class="text-link" data-article="${esc(v.articleId)}">テーマを読む ↗</button>`:''}<p class="fine">動画の時間は本文の読了目安に含みません。視聴には通信が必要です。${v.id?'再生ボタンを押すとYouTubeに接続します。':''}</p></article>`}

function collection(){const items=filtered(data.filter(a=>state.saved.includes(a.id)));return `<div class="page"><div class="eyebrow">YOUR CABINET OF CURIOSITIES</div><h1 class="route-title">心が動いた、世界のかけら。</h1><p class="route-intro">覚えるためではなく、また会いたくなるから。<br>あなたが集めた発見のコレクション。</p>${chips()}<div class="collection-channels"><p>${(state.channelSaves||[]).length} チャンネルを保存しています</p><a class="secondary" href="#channels" data-open-saved-channels>保存したチャンネルを見る</a></div>${heading('COLLECTED WONDERS',`${state.saved.length} 個の発見`,'並び順：最近保存したものから',`<button class="text-link" id="export">データを書き出す ↗</button>`)}<div class="exhibits">${items.sort((a,b)=>state.saved.indexOf(b.id)-state.saved.indexOf(a.id)).map(card).join('')}</div>${!items.length?'<div class="empty"><h2>心に残る発見を、ここに。</h2><p>展示の「＋」を押すと保存できます。<br>他の端末へ移すときは、データを書き出してください。</p><a class="text-link" href="#discover">探検に出かける ↗</a></div>':''}</div>`}
function atlas(){const viewed=data.filter(a=>state.visits[a.id]).length,cols=5,rows=Math.ceil(data.length/cols),height=rows*135+70,positions=data.map((a,i)=>[90+i%cols*174,55+Math.floor(i/cols)*135+(i%2)*18]);return `<div class="page"><div class="eyebrow">THE CONSTELLATION OF KNOWLEDGE</div><h1 class="route-title">発見は、星座になる。</h1><p class="route-intro">暮らしから科学へ。遊びから文明へ。<br>分野の境界を越えて、ひとつの疑問が次の世界を照らします。</p><p class="atlas-scroll-hint">星図は縦横にスクロールできます。星を選ぶと展示が開きます。</p><div class="atlas-shell"><svg viewBox="0 0 900 ${height}" style="width:900px;height:${height}px" role="group" aria-label="知識の関連を巡る星図。各星を選ぶと展示が開きます。">${data.map((a,i)=>a.related.map(id=>{const j=data.findIndex(x=>x.id===id);if(j<0)return '';return `<line x1="${positions[i][0]}" y1="${positions[i][1]}" x2="${positions[j][0]}" y2="${positions[j][1]}" stroke="#8eaf8c" stroke-opacity=".19"/>`}).join('')).join('')}${data.map((a,i)=>{const[x,y]=positions[i],known=!!state.visits[a.id];return `<g class="node" role="button" tabindex="0" aria-label="${esc(a.title)} ${known?'発見済み':'未探索'}" data-article="${a.id}" transform="translate(${x},${y})"><circle r="${known?12:8}" fill="${known?'#dbdca0':'#638d7d'}" stroke="#e3eacc" stroke-opacity="${known?.8:.3}" stroke-width="${known?5:1}"/><text x="0" y="30" text-anchor="middle" style="font-size:11px">${esc(a.title.replace(/[。、？]/g,'').slice(0,12))}</text><text x="0" y="47" text-anchor="middle" style="font-size:9px;fill:#a7bfae">${a.category}</text></g>`}).join('')}</svg></div><p class="fine">● 発見した星 ${viewed}　·　まだ知らない世界 ${data.length-viewed}</p><div class="tools-row"><button data-random>⤨ 知らない星に寄り道する</button><button id="atlas-known">出会った知識をたどる</button></div>${heading('UNEXPECTED CONNECTIONS','思いがけない、つながり。','アプリが用意した関連テーマ。未読の星も探検できます。')}<div class="exhibits">${data.filter(a=>['fold','wave','noise'].includes(a.id)).map(card).join('')}</div></div>`}
function lab(){return `<div class="page"><div class="eyebrow">THE INTERACTIVE LAB</div><h1 class="route-title">触れると、世界が動きだす。</h1><p class="route-intro">答えを当てなくていい。変えて、眺めて、気になったらもう一度。</p><div class="experiment-tabs"><button data-exp="pendulum" class="${expType==='pendulum'?'active':''}">01 振り子のリズム</button><button data-exp="illusion" class="${expType==='illusion'?'active':''}">02 同じ灰色、違う灰色</button><button data-exp="chance" class="${expType==='chance'?'active':''}">03 偶然を眺める</button></div><section id="experiment" class="experiment"></section></div>`}
function setupExperiment(){cancelAnimationFrame(raf);let el=$('#experiment');if(!el)return;
if(expType==='pendulum'){el.innerHTML=`<div class="eyebrow">PHYSICS / SMALL-ANGLE MODEL</div><h2>長くすると、どれだけゆっくり？</h2><p>ひもの長さを変えてみてください。比較用の薄い振り子は、長さ1 m。小さな振れ幅・摩擦なしの理想モデルです。</p><canvas id="pendulum" aria-label="長さを変えると周期が変わる振り子の図"></canvas><div class="control"><label for="length">ひもの長さ</label><input id="length" type="range" min="0.25" max="2" step="0.05" value="1"><output id="length-out">1.00 m</output></div><div class="tools-row"><button id="pause">一時停止</button><button id="restart">はじめから</button></div><div>一往復の時間 <span class="stat" id="period">2.01</span> 秒</div><p>T = 2π√(L/g)、g = 9.81 m/s²。長さを4倍にすると周期は2倍になります。モデルの動きは実際の秒数に合わせています。</p><button class="text-link" data-article="wave">振り子の展示へ ↗</button>`;
let c=$('#pendulum'),ctx=c.getContext('2d'),time=0,last=0,paused=false;$('#pause').onclick=()=>{paused=!paused;$('#pause').textContent=paused?'再開する':'一時停止'};$('#restart').onclick=()=>{time=0};const frame=now=>{if(!c.isConnected)return;let rect=c.getBoundingClientRect(),dpr=devicePixelRatio||1;if(c.width!==Math.round(rect.width*dpr)||c.height!==Math.round(rect.height*dpr)){c.width=Math.round(rect.width*dpr);c.height=Math.round(rect.height*dpr)}ctx.setTransform(dpr,0,0,dpr,0,0);let w=rect.width,h=rect.height,L=Number($('#length').value),T=2*Math.PI*Math.sqrt(L/9.81);if(last&&!paused)time+=Math.min((now-last)/1000,.1);last=now;$('#length-out').textContent=L.toFixed(2)+' m';$('#period').textContent=T.toFixed(2);ctx.clearRect(0,0,w,h);[[1,'#b6c2af',w*.35],[L,'#385e45',w*.65]].forEach(([l,col,x])=>{let len=65+l*60,theta=.20*Math.cos(Math.sqrt(9.81/l)*time),y=25,bx=x+Math.sin(theta)*len,by=y+Math.cos(theta)*len;ctx.strokeStyle=col;ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(bx,by);ctx.stroke();ctx.fillStyle=col;ctx.beginPath();ctx.arc(bx,by,12,0,Math.PI*2);ctx.fill();ctx.font='11px sans-serif';ctx.textAlign='center';ctx.fillText(l.toFixed(2)+' m',x,h-18)});raf=requestAnimationFrame(frame)};raf=requestAnimationFrame(frame)
}else if(expType==='illusion'){el.innerHTML=`<div class="eyebrow">PERCEPTION / SIMULTANEOUS CONTRAST</div><h2>このふたつ、同じ明るさです。</h2><p>左右の四角は、どちらも同じ灰色（#888888）。背景との関係で、違う明るさに見えることがあります。</p><div class="illusion" id="illusion"><span></span><span></span></div><div class="tools-row"><button class="primary" id="reveal">背景を外してみる</button></div><p>目の順応や周囲との比較が、明るさの知覚に関わります。画面や視覚の個人差によって感じ方は異なります。</p><button class="text-link" data-article="color">色の見え方の展示へ ↗</button><div class="source-list"><a href="https://www.exploratorium.edu/snacks/gray-step" target="_blank" rel="noopener">仕組みの出典：Exploratorium — Gray Step ↗</a></div>`;$('#reveal').onclick=()=>{const on=$('#illusion').classList.toggle('reveal');$('#reveal').textContent=on?'背景を戻す':'背景を外してみる'}
}else{el.innerHTML=`<div class="eyebrow">PROBABILITY / INDEPENDENT TRIALS</div><h2>偶然は、少しでこぼこしている。</h2><p>表の確率が50%のコインをシミュレーションします。少ない回数では偏り、大きな回数では比率がどう変化するか眺めてみましょう。</p><canvas id="chance-chart" aria-label="試行回数に対する表の割合。中央の線は50パーセント"></canvas><div class="tools-row"><button class="primary" data-flip="10">10回投げる</button><button class="secondary" data-flip="100">100回投げる</button><button class="secondary" id="reset-coins">リセット</button></div><p id="chance-status" aria-live="polite">まだ投げていません。</p><p>点線は50%。前の結果は次の確率を変えません。これは擬似乱数による教材で、賭け事の予測には使えません。</p><button class="text-link" data-article="chance">偶然の展示へ ↗</button>`;let n=0,heads=0,points=[],c=$('#chance-chart'),ctx=c.getContext('2d');function draw(){const r=c.getBoundingClientRect(),d=devicePixelRatio||1;c.width=r.width*d;c.height=r.height*d;ctx.scale(d,d);const w=r.width,h=r.height;ctx.clearRect(0,0,w,h);ctx.setLineDash([5,5]);ctx.strokeStyle='#a8b99c';ctx.beginPath();ctx.moveTo(30,h/2);ctx.lineTo(w-10,h/2);ctx.stroke();ctx.setLineDash([]);ctx.strokeStyle='#3c6549';ctx.lineWidth=1.5;ctx.beginPath();points.forEach((p,i)=>{const x=30+i/Math.max(1,points.length-1)*(w-45),y=15+(1-p)*(h-35);i?ctx.lineTo(x,y):ctx.moveTo(x,y)});ctx.stroke();ctx.fillStyle='#65755b';ctx.font='10px sans-serif';ctx.fillText('100%',0,18);ctx.fillText('50%',0,h/2);ctx.fillText('0%',5,h-20)}$$('[data-flip]',el).forEach(b=>b.onclick=()=>{if(n>=10000){toast('1万回を観察しました。リセットして新しい偶然へ。');return}for(let i=0;i<Number(b.dataset.flip);i++){n++;if(Math.random()<.5)heads++;points.push(heads/n)}$('#chance-status').textContent=`${n}回投げました。表 ${heads}回 / 裏 ${n-heads}回。表の割合 ${(100*heads/n).toFixed(1)}%。`;draw()});$('#reset-coins').onclick=()=>{n=0;heads=0;points=[];$('#chance-status').textContent='まだ投げていません。';draw()};draw()}}
function render(){cancelAnimationFrame(raf);const route=location.hash.slice(1)||'discover';$$('nav a').forEach(a=>a.classList.toggle('active',a.hash==='#'+route));$('#app').innerHTML=route.startsWith('room-')?roomPage(route.slice(5)):route==='atlas'?atlas():route==='collection'?collection():route==='lab'?lab():route==='channels'?channelPage():route==='watch'||route.startsWith('watch-')?watchPage(route.slice(6)):route==='videos'?`<div class="page">${mediaNavigation('videos')}<div class="eyebrow">WATCH & WONDER</div><h1 class="route-title">映像で、腑に落ちる。</h1><p class="route-intro">人気の数字より、理解のきっかけを。<br>すべての展示に日本語の参考映像を用意しました。日本語音声・字幕・日本語解説付き観察映像を明示しています。関連動画の範囲も各説明で確認できます。</p><div class="video-grid">${videoList().map(videoCard).join('')}</div></div>`:discover();if($('#duration'))$('#duration').value=duration;if(route==='lab')setupExperiment();updateCount()}
function read(id){let a=data.find(x=>x.id===id);if(!a)return;activeArticle=a;let v=state.visits[id];state.visits[id]={first:v?.first||Date.now(),last:Date.now(),count:(v?.count||0)+1};persist();$('#reader-body').innerHTML=`<div class="reader-hero"><img src="./assets/${a.image}.jpg" alt="${esc(a.subtitle)}のイメージ写真"></div><div class="reader-content"><div class="eyebrow">${a.category} / FIELD NOTE ${String(a.number).padStart(2,'0')}</div><h1>${esc(a.title)}</h1><p class="lead">${esc(a.summary)}</p><div class="tools-row"><button aria-label="発見を保存・解除" data-save="${id}" class="secondary ${state.saved.includes(id)?'saved':''}">${state.saved.includes(id)?'✓':'+'}</button><button id="reader-talk-link">一言で話す ↘</button><button id="reader-gpt-link">GPTと深掘り ↘</button></div><div class="read-modes" aria-label="読み方"><button data-mode="short" aria-pressed="false">要点だけ</button><button class="active" data-mode="full" aria-pressed="true">背景まで読む</button><button data-mode="deep" aria-pressed="false">動画・出典へ</button></div><p class="reading-estimate">本文 約${readingMinutes(a)}分 · ${a.sections.reduce((n,s)=>n+s.text.length,0).toLocaleString()}字<span>1分350字で算出した目安。動画・実験の時間は別です。</span></p><div class="fact"><strong>ひとつ、持ち帰るなら。</strong><p>${esc(a.sections[0].text)}</p></div>${articleExperience(a)}<div class="more-section"><div class="reader-map"><div class="eyebrow">IN THIS FIELD NOTE</div>${a.sections.map((s,i)=>`<a href="#reader-section-${i}" data-section="reader-section-${i}"><small>${String(i+1).padStart(2,'0')}</small>${esc(s.heading)}</a>`).join('')}</div>${a.sections.map((s,i)=>`<section class="article-section" id="reader-section-${i}"><h2>${esc(s.heading)}</h2><p>${esc(s.text)}</p></section>`).join('')}<p class="fine">本文は入門解説です。観察の提案と日常への応用例は、本アプリの編集内容です。研究の詳細・原典の条件は日本語の参考資料で確認できます。</p></div>${['wave','color','chance'].includes(id)?`<a class="text-link" href="#lab" id="article-lab">手を動かして確かめる ↗</a>`:''}<section class="talk" id="talk"><div class="eyebrow">A LITTLE SOMETHING TO SHARE</div><p>${esc(a.talk)}</p><button class="text-link" id="copy-talk">30秒の雑談をコピーする　↗</button></section><section class="bridge" id="bridge"><div class="eyebrow">CONTINUE WITH CHATGPT</div><h3>この「なぜ？」の、その先へ。</h3><label for="bridge-mode">どんなふうに話してみる？</label><select id="bridge-mode"><option>知識を深掘りする</option><option>雑談ネタとして発展させる</option><option>創作のアイデアとして検討する</option><option>目的を決めずに共有する</option></select><label for="bridge-part" class="fine">引き継ぐ一部分・質問（空欄なら記事全体）</label><textarea id="bridge-part" placeholder="気になる段落を選択して下のボタンで取り込む、または質問を書く"></textarea><button class="text-link" id="use-selection">選択した文章を取り込む</button><div><button class="primary" id="copy-bridge">引き継ぎ文をコピー</button><a class="secondary" href="https://chatgpt.com/" target="_blank" rel="noopener">ChatGPTを開く ↗</a></div><p class="fine">コピーしてChatGPTに貼り付けると、出典と前提をまとめて渡せます。アプリ内対話・API課金はありません。</p></section><section class="article-videos" id="article-videos"><div class="eyebrow">WATCH & UNDERSTAND</div><h2>動きで、確かめる。</h2>${a.videos.map(videoCard).join('')}</section>${articleChannels(a)}<section class="source-list" id="sources"><h2>日本語で、もっと知る。</h2>${a.sources.map(s=>`<a href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.name)} <small>日本語${s.url.includes('.pdf')?' · PDF':''}</small> ↗</a>`).join('')}<small>出典確認日：${a.checked}${a.review?'（生成記事・自動出典照合）':''} · 写真はテーマのイメージです（Unsplash）。</small></section><h2>次の寄り道。</h2><div>${a.related.map(id=>{const r=data.find(x=>x.id===id);return r?`<button class="search-result" data-article="${id}"><small>${r.category}</small>${esc(r.title)}　↗</button>`:''}).join('')}</div></div>`;if(!$('#reader').open)$('#reader').showModal();$('#reader').scrollTop=0;setupArticleExperience(a);$('#copy-talk').onclick=()=>copy(a.talk);$('#reader-talk-link').onclick=()=>$('#talk').scrollIntoView({behavior:'smooth'});$('#reader-gpt-link').onclick=()=>$('#bridge').scrollIntoView({behavior:'smooth'});$('#copy-bridge').onclick=()=>copy(bridgeText(a));$('#use-selection').onclick=()=>{const selection=window.getSelection()?.toString().trim();if(selection){$('#bridge-part').value=selection;toast('選択した文章を取り込みました')}else toast('記事中の気になる文章を長押しして選択してください')};if($('#article-lab'))$('#article-lab').onclick=()=>{$('#reader').close();expType=id==='wave'?'pendulum':id==='color'?'illusion':'chance';if(location.hash==='#lab')render()};$$('[data-mode]',$('#reader')).forEach(b=>b.onclick=()=>{$$('[data-mode]',$('#reader')).forEach(x=>x.classList.toggle('active',x===b));$('.more-section',$('#reader')).hidden=b.dataset.mode==='short';$$('[data-mode]',$('#reader')).forEach(x=>x.setAttribute('aria-pressed',String(x===b)));if(b.dataset.mode==='deep')$('#article-videos').scrollIntoView({behavior:'smooth'})})}
function bridgeText(a){return `【Curiosity Labからの引き継ぎ】\nテーマ：${a.title}\n依頼モード：${$('#bridge-mode').value}\n概要：${a.summary}\n重要な事実：\n${a.sections.map(s=>s.heading+'：'+s.text).join('\n')}\n出典（確認日 ${a.checked}）：\n${a.sources.map(s=>s.name+' '+s.url).join('\n')}\n日本語の参考動画：\n${a.videos.map(v=>v.title+' '+v.url+'（'+v.note+'）').join('\n')}\n関連情報：${a.related.map(id=>data.find(x=>x.id===id)?.title||'').filter(Boolean).join(' / ')}\n選択部分・質問：${$('#bridge-part').value||'記事全体を共有します。'}\n依頼：上記のモードで対話を始めてください。出典の事実、推測、創作案を区別してください。創作への転用は私が判断します。前提を繰り返し質問せず、まず内容に即した提案をしてください。`}
