function settings(){const d=document.createElement('dialog');d.innerHTML=`<div class="reader-content"><form method="dialog"><button class="secondary">閉じる ×</button></form><h1>あなたの発見を、大切に。</h1><p>保存と閲覧履歴は、この端末・このブラウザーに保存されます。アカウントへの同期はありません。ホーム画面版とSafariの保存領域が異なる場合は、書き出しと読み込みで移せます。</p><div class="tools-row"><button id="data-export" class="primary">書き出す</button><label class="secondary" for="import-data">データを読み込む</label><input type="file" id="import-data" accept="application/json" hidden></div><h2>ホーム画面から、博物館へ。</h2><p>iPhoneのSafariで開き、共有 →「ホーム画面に追加」を選んでください。一度開いた展示や実験はオフラインでも利用できます。動画、外部出典、ChatGPTには通信が必要です。</p><h2>もう一度出会う</h2><p>初めて触れてから3日以上たった知識を、トップに別の切り口で再表示します。同じ展示の再表示は7日以上空けます。通知やテストはありません。</p><h2>コンテンツと更新</h2>${updatePanel()}<p>現在${data.length}テーマと8つの展示室、${channelCatalog.channels.length}チャンネルの探索ガイドを公開しています。全展示に日本語の参考資料と動画を表示しています。GitHub Actionsで毎週月・水・金の朝7時（日本時間）に、事前確認済みの記事を1件ずつ追加する設定です。配信待ち件数と最終追加日は上に表示しています。候補が尽きた場合は追加待ちと表示し、既存の展示を残します。候補の補充は編集作業が必要で、無制限の自動生成は有効にしていません。更新時には日本語資料・日本語動画・本文量の検査を行います。</p><p>動画の100点評価は実視聴による検証待ちです。未確認の点数は付けていません。写真は説明対象そのものを保証するものではなく、テーマのイメージです。</p><h2>写真について</h2><p>画像提供：Unsplash。星雲、クラゲ、森、地球、海、都市、エジプトの写真を使用しています。写真の配信元URLと利用条件はソース内のASSETS.mdに記載しています。</p><p class="fine">Curiosity Lab v1.4 · 2026.11.24 · 世界を知ることを、娯楽に。</p></div>`;document.body.append(d);d.showModal();d.onclose=()=>d.remove();$('#data-export',d).onclick=exportData;$('#import-data',d).onchange=async e=>{try{const file=e.target.files[0];if(file.size>2e6)throw Error();const s=JSON.parse(await file.text());if(s.app!=='CuriosityLab'||!Array.isArray(s.saved)||!s.visits||!s.reencounters)throw Error();let visits={...state.visits};for(const [id,v]of Object.entries(s.visits)){if(data.some(a=>a.id===id)&&v&&Number.isFinite(v.first)&&Number.isFinite(v.last)&&Number.isFinite(v.count))visits[id]=v}state={saved:[...new Set([...state.saved,...s.saved.filter(id=>data.some(a=>a.id===id))])],visits,channelSaves:[...new Set([...(state.channelSaves||[]),...(Array.isArray(s.channelSaves)?s.channelSaves.filter(id=>channelById(id)):[])])],reencounters:{...state.reencounters,...Object.fromEntries(Object.entries(s.reencounters).filter(([id,v])=>data.some(a=>a.id===id)&&Number.isFinite(v)))}};persist();render();toast('発見を読み込みました');d.close()}catch{toast('Curiosity Labの書き出しファイルを選んでください')}}}
document.addEventListener('click',e=>{if(e.target.closest('[data-open-saved-channels]'))channelOrigin='saved';const routeLink=e.target.closest('a[href^="#"]');if(routeLink&&$('#reader').open&&routeLink.hash===location.hash){$('#reader').close();render()}const section=e.target.closest('[data-section]');if(section){e.preventDefault();document.getElementById(section.dataset.section)?.scrollIntoView({behavior:'smooth'});return}const s=e.target.closest('[data-save]');if(s){e.stopPropagation();save(s.dataset.save);return}const a=e.target.closest('[data-article]');if(a){read(a.dataset.article);return}const f=e.target.closest('[data-filter]');if(f){filter=f.dataset.filter;render();return}if(e.target.closest('[data-random]')){const unvisited=data.filter(a=>!state.visits[a.id]),pool=unvisited.length?unvisited:data;read(pool[Math.floor(Math.random()*pool.length)].id);return}const v=e.target.closest('[data-video]');if(v){v.closest('.video-preview').innerHTML=`<iframe src="https://www.youtube-nocookie.com/embed/${v.dataset.video}?autoplay=1&cc_load_policy=1&cc_lang_pref=ja" title="日本語で確認できる参考動画" allow="autoplay; encrypted-media; picture-in-picture" allowfullscreen referrerpolicy="strict-origin-when-cross-origin"></iframe>`;return}const x=e.target.closest('[data-exp]');if(x){expType=x.dataset.exp;render();return}const re=e.target.closest('[data-revisit]');if(re){state.reencounters[re.dataset.revisit]=Date.now();persist();read(re.dataset.revisit)}if(e.target.closest('#export'))exportData();if(e.target.closest('#atlas-known')){const found=data.filter(a=>state.visits[a.id]);found.length?read(found[Math.floor(Math.random()*found.length)].id):toast('まだ白紙の星図です。気になる星を選んでみましょう。')}});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[role="button"]')){e.preventDefault();e.target.click()}});document.addEventListener('change',e=>{if(e.target.id==='duration'){duration=e.target.value;render()}});$('.close-reader').onclick=()=>$('#reader').close();$('#reader').addEventListener('close',()=>{activeArticle=null;if(['#atlas','#collection'].includes(location.hash))render()});$('#settings').onclick=settings;$('#search-open').onclick=()=>{$('#search-dialog').showModal();$('#search-input').focus();search()};function search(){let q=$('#search-input').value.trim().toLowerCase(),matches=data.filter(a=>[a.title,a.summary,a.category,a.subtitle,...(a.rooms||[]).map(id=>ROOMS.find(r=>r.id===id)?.short||'')].join(' ').toLowerCase().includes(q));$('#search-results').innerHTML=matches.length?matches.map(a=>`<button class="search-result" data-article="${a.id}"><small>${a.category} · 本文 約${readingMinutes(a)}分</small>${esc(a.title)} ↗</button>`).join(''):'<p>まだ展示されていないテーマです。別の言葉でも探してみてください。</p>'}$('#search-results').onclick=e=>{if(e.target.closest('[data-article]'))$('#search-dialog').close()};$('#search-input').oninput=search;window.addEventListener('hashchange',()=>{if($('#reader').open)$('#reader').close();render();window.scrollTo(0,0)});
function updatePanel(){
 const newest=[...data].sort((a,b)=>(b.published||'').localeCompare(a.published||'')||b.number-a.number)[0];
 const status=updateStatus?.contentVersion===contentMeta.version?updateStatus:null;
 const label=!status?'配信状況を確認できませんでした':status.status==='failed'?'前回の追加に失敗しました':status.status==='awaiting-review'?'次の配信候補の追加待ち':`次の配信候補 ${status.remaining}件`;
 return `<section class="update-panel" aria-label="展示の更新状況"><div><div class="eyebrow">NEW IN THE LAB</div><p class="update-date">最終追加 ${esc(status?.lastAdded||contentMeta.updated||'不明')} · ${data.length}テーマ</p>${newest?`<button class="newest-title" data-article="${esc(newest.id)}">${esc(newest.title)}</button>`:''}<p class="update-note">${esc(label)} · 月・水・金 朝7時予定</p></div><button class="secondary" data-check-updates>最新情報を確認</button></section>`;
}
async function refreshContent(manual=false){
 if(refreshing||!manual&&Date.now()-lastContentCheck<60000)return;
 if($('#reader').open&&!manual)return;
 refreshing=true;
 try{
  const response=await fetch('./content.json',{cache:'no-store'});
  if(!response.ok)throw Error();
  const content=await response.json();
  if(!Array.isArray(content.articles)||!content.articles.length)throw Error();
  // A service worker may supply a cached response offline; never label that a successful live check.
  if(response.headers.get('X-Curiosity-Offline')==='1')throw Error();
  const status=await fetch('./update-status.json',{cache:'no-store'}).then(r=>r.ok?r.json():null).catch(()=>null);
  const changed=content.version!==contentMeta.version;
  contentMeta=content;data=content.articles;updateStatus=status;lastContentCheck=Date.now();
  if(!$('#reader').open)render();
  $$('.update-panel').forEach(p=>p.outerHTML=updatePanel());
  if(manual||changed)toast(changed?'新しい展示を読み込みました':'最新の展示を確認しました');
  if('serviceWorker'in navigator){const registration=await navigator.serviceWorker.getRegistration();registration?.update().catch(()=>{});}
 }catch{if(manual)toast('通信できませんでした。保存済みの展示を表示しています。');}
 finally{refreshing=false;}
}
document.addEventListener('click',e=>{if(e.target.closest('[data-check-updates]'))refreshContent(true);if(e.target.closest('[data-reload-app]'))location.reload()});
document.addEventListener('visibilitychange',()=>{if(!document.hidden)refreshContent()});
window.addEventListener('online',()=>refreshContent());
if('serviceWorker'in navigator){let controlled=!!navigator.serviceWorker.controller;navigator.serviceWorker.addEventListener('controllerchange',()=>{if(controlled&&!$('#reload-app')){const button=document.createElement('button');button.id='reload-app';button.className='app-update-button';button.dataset.reloadApp='';button.textContent='新しい画面に更新';document.body.append(button);}controlled=true;});}
async function boot(){try{const [res,catalog,status]=await Promise.all([fetch('./content.json',{cache:'no-cache'}),fetch('./channels.json',{cache:'no-cache'}).then(r=>{if(!r.ok)throw Error();return r.json()}).catch(()=>null),fetch('./update-status.json',{cache:'no-cache'}).then(r=>r.ok?r.json():null).catch(()=>null)]);if(validChannelCatalog(catalog))channelCatalog=catalog;if(!res.ok)throw Error();const content=await res.json();data=content.articles;if(!Array.isArray(data)||!data.length)throw Error();contentMeta=content;updateStatus=status;lastContentCheck=Date.now();render();if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js',{updateViaCache:'none'}).catch(()=>{});}catch{$('#app').innerHTML='<div class="page empty"><h1>展示の準備に接続できませんでした。</h1><p>初めての起動には通信が必要です。</p><button class="primary" onclick="location.reload()">もう一度開く</button></div>'}}boot();
